}

node Note {
  text: <text>
}

movement persist_pair(c: <Lead>, n: <Note>) {
  crm = attio(credentials: acme_main)
  write crm-[:companies]-> {
    unique by (`name`)
    name:    c.`name`
    summary: n.`text`
  }
}

movement intake(msg: <inbox-[:message]->>) {
  persist_pair(c: node { name: msg.`subject` }, n: node { text: msg.`text` })
}

