chat = slack()
crm = attio()

movement m(c: <chat-[:channel]->>) {
  lines = COLLECT(c-[m:Messages]->.`Text`)
  all = REDUCE(lines, "", (carried, t) => { return CONCAT(carried, t) })
  write chat-[:note]-> { Body: all }
}

