runs = manual()
graph = kg(credentials: kg_cred)
movement recap(go: <runs-[:Invocation]->>) {
  x = FIRST(graph-[n:note ORDER BY `body`]->)
  await sleep(1h)
  write graph-[:note]-> { payload: { b: x.`body` } }
}
listen to runs {} fire recap

