node Doc {
  title: <text>
  node files {
    name: <text>
    blob: <file>
  }
}

movement email_to_doc(m: <inbox-[:message]->>) {
  return node {
    title: m.`Subject`
    files: lazy m-[a:Attachments]-> node { name: a.`Name`, blob: a.`File` }
  }
}

