import { email, attio } from adapters
import { inbox_cred, acme_main } from credentials
inbox = email(credentials: inbox_cred)
movement m(msg: <inbox-[:message]->>) {
  crm = attio(credentials: acme_main)
  rehearsed = attio(credentials: acme_main, dry_run: true)
  h0 = write crm-[:companies]-> { unique by (FUZZY `name`), name: "Acme Incorporated", domain : "new.example" }
  MAP(["Acme Incorporated", "Beta Ltd"], (n) => {
    o1 = write crm-[:companies]-> { unique by (`name`), name: n, domain ?: "new.example" }
    o1-[w2:@old]-> {
      write crm-[:notes]-> { title: COALESCE(w2.`domain`, "none") }
    }
  })
  m3 = match crm-[:companies]-> { unique by (FUZZY `name`), name: "Acme Incorporated" }
  write crm-[:notes]-> { title: IF m3 == null THEN "absent" ELSE COALESCE(m3.`domain`, "none") END }
  if m3 != null {
    x4 = write m3 { domain: "old.example" }
    write crm-[:notes]-> { title: COALESCE(m3.`domain`, "none") }
    write crm-[:notes]-> { title: COALESCE(x4.`name`, "none") }
  }
  h5 = write crm-[:companies]-> { unique by (`name`), name: "Beta Ltd", domain ?: "new.example" }
  MAP(["Beta Ltd", "Acme Incorporated"], (n) => {
    o6 = write crm-[:companies]-> { unique by (`name`), name: n, domain : "second.example" }
    write crm-[:notes]-> { title: IF FIRST(o6-[:@old]->) == o6 THEN "self" ELSE "other" END }
  })
  m7 = match crm-[:companies]-> { unique by (FUZZY `name`), name: "Acme Incorporated" }
  write crm-[:notes]-> { title: IF m7 == null THEN "absent" ELSE COALESCE(m7.`domain`, "none") END }
  if m7 != null {
    x8 = write m7 { domain: "new.example" }
    write crm-[:notes]-> { title: COALESCE(m7.`domain`, "none") }
    x8-[w9:@old WHERE w9.`domain` == "new.example"]-> {
      write crm-[:notes]-> { title: COALESCE(w9.`name`, "none") }
    }
  }
  write crm-[:notes]-> { title: COALESCE(h5.`domain`, "none") }
}

