inbox = email(credentials: inbox_cred)
movement m(msg: <inbox-[:message]->>) {
  crm = attio(credentials: acme_main)
  rehearsed = attio(credentials: acme_main, dry_run: true)
  h0 = write crm-[:companies]-> { unique by (`name`), name: "Beta Ltd", domain : "third.example" }
  h1 = write crm-[:companies]-> { unique by (`name`), name: "Acme Incorporated", domain : "old.example" }
  write crm-[:notes]-> { title: COALESCE(h1.`name`, "none") }
  MAP(["Beta Ltd", "Acme Incorporated"], (n) => {
    o2 = write crm-[:companies]-> { unique by (`name`), name: n, domain : "second.example" }
    write crm-[:notes]-> { title: COALESCE(FIRST(o2-[:@old]->).`domain`, "none") }
  })
}

