  crm = attio(credentials: acme_main)
  rehearsed = attio(credentials: acme_main, dry_run: true)
  h0 = write rehearsed-[:companies]-> { unique by (`name`), name: "Acme Incorporated", domain : "second.example" }
  write crm-[:notes]-> { title: COALESCE(FIRST(h0-[:@old]->).`domain`, "none") }
  was1 = FIRST(h0-[:@old]->)
  if was1 != null {
    write crm-[:notes]-> { title: COALESCE(was1.`domain`, "none") }
    write crm-[:notes]-> { title: IF was1 == h0 THEN "same" ELSE "distinct" END }
    write crm-[:notes]-> { title: IF EXISTS(was1-[:@old]->) THEN "older" ELSE "first" END }
    write crm-[:notes]-> { title: COALESCE(FIRST(was1-[:@old]->).`domain`, "none") }
  }
  h2 = write crm-[:companies]-> { unique by (`name`), name: "Beta Ltd", domain : "old.example" }
  h3 = write crm-[:companies]-> { unique by (`name`), name: "Newco", domain ?: "old.example" }
}

