inbox = email(credentials: inbox_cred)
movement m(msg: <inbox-[:message]->>) {
  crm = attio(credentials: acme_main)
  rehearsed = attio(credentials: acme_main, dry_run: true)
  h0 = write rehearsed-[:companies]-> { unique by (`name`), name: "Newco", domain : "second.example" }
  write h0 { domain: "third.example" }
  if TRUE {
    write crm-[:notes]-> { title: COALESCE(h0.externalId, "none") }
  }
  h1 = write crm-[:companies]-> { name: "Acme Incorporated", domain : "third.example" }
  m2 = match crm-[:companies]-> { unique by (FUZZY `name`), name: "Newco" }
  write crm-[:notes]-> { title: IF m2 == null THEN "absent" ELSE COALESCE(m2.`domain`, "none") END }
  if m2 != null {
    write crm-[:notes]-> { title: COALESCE(m2.`name`, "none") }
  }
  h3 = write crm-[:companies]-> { unique by (`name`), name: "Acme Incorporated", domain : "third.example" }
  if TRUE {
    m4 = match crm-[:companies]-> { unique by (`name`), name: "Newco" }
    write crm-[:notes]-> { title: IF m4 == null THEN "absent" ELSE COALESCE(m4.`domain`, "none") END }
    if m4 != null {
      x5 = write m4 { domain: "old.example" }
      write crm-[:notes]-> { title: COALESCE(m4.`domain`, "none") }
      write crm-[:notes]-> { title: COALESCE(x5.`domain`, "none") }
    }
  }
}

import { email, attio } from adapters
import { inbox_cred, acme_main } from credentials
