  h0 = write rehearsed-[:companies]-> { unique by (`name`), name: "Newco", domain : "second.example" }
  x1 = write h0 { domain ?: "new.example" }
  write crm-[:notes]-> { title: IF x1 == h0 THEN "same" ELSE "distinct" END }
  MAP(["Beta Ltd", "Acme Incorporated"], (n) => {
    o2 = write crm-[:companies]-> { unique by (`name`), name: n, domain ?: "third.example" }
    write crm-[:notes]-> { title: IF EXISTS(o2-[w3:@old WHERE w3.`name` == o2.`name`]->) THEN "kept" ELSE "not" END }
  })
  write h0 { domain: "new.example" }
  h4 = write crm-[:companies]-> { unique by (`name`), name: "Newco", domain : "old.example" }
  write crm-[:notes]-> { title: COALESCE(h4.`name`, "none") }
  write crm-[:notes]-> { title: COALESCE(FIRST(x1-[:@old]->).`domain`, "none") }
}

