inbox = email(credentials: inbox_cred)
src = attio(credentials: crm_cred)
sink = sheets(credentials: sheet_cred)
node Entry: "each company named in this message" {
  name: <text> "the company's name"
  tag: <text> "its tag"
  node child: "each founder" {
    first: <text> "first name"
  }
}
node Holder {
  name: <text>
  node entries {
    name: <text>
    tag: <text>
    node child {
      first: <text>
    }
  }
}
movement use_entry(e: <Entry>) {
  write sink-[:rows]-> { v: e.name }
}
movement pairs_entry(e: <Entry>) {
  write sink-[:rows]-> { v: TEXT.PAIRS(e) }
}
movement serialise_entry(e: <Entry>) {
  write sink-[:rows]-> { v: TEXT.SERIALISE(e, "JSON") }
}
movement child_entry(e: <Entry>) {
  e-[k:child]-> {
    write sink-[:rows]-> { v: k.first }
  }
}
movement serialise_child(e: <Entry>) {
  e-[k:child]-> {
    write sink-[:rows]-> { v: TEXT.SERIALISE(k, "JSON") }
  }
}
movement summarise_entry(e: <Entry>) {
  s = summarise(data: e)
  write sink-[:rows]-> { v: s }
}
movement run_cell(msg: <inbox-[:message]->>) {
  deduped = node { entries: <Entry> order by arrival }
  copies = node { entries: <Entry> order by arrival }
  a = write deduped-[:entries]-> { name: "Acme", tag: "a" }
  write a-[:child]-> { first: "Ann" }
  b = write deduped-[:entries]-> { name: "Beta", tag: "b" }
  write b-[:child]-> { first: "Bob" }
  x = AT(deduped-[:entries]->, 1)
  if x == null { ERROR("no record") }
  page = fetch_url(url: x)
  write sink-[:rows]-> { v: COALESCE(page, "none") }
}

