    return write crm-[:companies]-> {
      unique by (`name`)
      name: c.`name`
    }
  }

  write team-[:messages]-> {
    channel: "#deals"
    text: "Logged ${COUNT(mentioned-[:company]->)} companies. Urls: ${orgs.`url`}"
  }
}

