inbox = email()
book = crm(credentials: crm_creds)

node Deal {
  title: <text>
  amount: <number>
  node company {
    name: <text>
  }
}

movement takes_deal(d: <Deal>) {
}

movement takes_company(c: <book-[:company]->>) {
}

node Doc {
  title: <text>
  node files {
    Name: <text>
    File: <file>
  }
}

movement takes_doc(d: <Doc>) {
}

node Renamed {
  title: <text>
  node files {
    blob: <file>
  }
}

movement takes_renamed(d: <Renamed>) {
}

node `Multi Words` {
  title: <text>
  node `Nested Edge` {
    label: <text>
  }
}

movement takes_multi(d: <`Multi Words`>) {
}

movement m(e: <inbox-[:message]->>) {
  takes_company(c: e)
}

