    () => {
      left = write inbox-[:messages]-> {
        channel: "#left"
        text:    co.externalId
      }
      return left.externalId
    },
    () => {
      right = write inbox-[:messages]-> {
        channel: "#right"
        text:    co.externalId
      }
      return right.externalId
    },
  ])
  write inbox-[:messages]-> {
    channel: "#after"
    text:    "${AT(r, 0)}/${AT(r, 1)}"
  }
}

