import { `@lf/email` as email, `@lf/attio` as attio } from adapters
import { dealflow_inbox, acme_main } from credentials
inbox = connect email using dealflow_inbox
crm = connect attio using acme_main

node FoundShape: "the relevant information in the content" {
  node company: "each company named" {
    name: <text> "its name"
    node person: "each person at it" {
      name: <text> "their name"
    }
  }
}

function m(msg: <inbox-[:message]->>) {
  found = extractOne([msg.`text`], FoundShape, { tier: "careful" })
  found-[c:company]-> {
    write crm-[:companies]-> { name: c.name }
    c-[p:person]-> {
      write crm-[:companies]-> { name: "${c.name}: ${p.name}" }
    }
  }
}

