import { attio, ledger } from adapters
import { crm_cred, ledger_cred } from credentials
import { summarise, relay, tag, ocr } from plugins

crm = connect attio using crm_cred
l = connect ledger using ledger_cred
function two() {
  a = write crm-[:companies]-> { name: "A" }
  b = write crm-[:companies]-> { name: "B" }
  return coalesce(a, b)
}
function mixed() {
  a = write crm-[:companies]-> { name: "A" }
  return coalesce(a, "x")
}
function m() {
  org = write crm-[:companies]-> { name: "Acme Inc." }
  f = File.from("contents", "pdf")
  o2 = write crm-[:companies]-> { name: "Other" }
  c = () => coalesce(org, "x")
  g = graph { a: c() }
}

