team  = connect slack using acme_workspace
timer = connect cron
function digest(t: <timer-[:tick]->>) {
  write team-[:message]-> { text: t.`firedAt` }
}
listen to timer { schedule: "0 9 * * 1", timezone: "Europe/London" } fire digest

