inbox = connect email

node Lead {
  name: <text>
}

node Note {
  text: <text>
}
function persist(name: <text>, cfg: <{ summary: text }>) {
  crm = connect attio using acme_main
  write crm-[:companies]-> {
    unique by (`name`)
    name:    name
    summary: cfg["summary"]
  }
}

function intake(msg: <inbox-[:message]->>) {
  persist(cfg: { summary: "named" }, name: msg.`subject`)
}

