import { email, attio } from adapters
import { acme_main } from credentials

inbox = email()

node Lead {
  name: <text>
}

movement persist(c: <Lead>) {
  crm = attio(credentials: acme_main)
  write crm-[:companies]-> {
    unique by (`name`)
    name: c.`name`
  }
}

movement relay(c: <Lead>) {
  persist(c: c)
}

movement intake(msg: <inbox-[:message]->>) {
  lead = node { name: msg.`subject` }
  relay(c: lead)
}

