}
function m(msg: <inbox-[:message]->>) {
  pieces = [msg.`subject`, msg.`text`]
  results = map(pieces, (p) => {
    return { piece: p, entries: extract([p], Company, { tier: 'careful' }) }
  })
  map(results, (x) => {
    kept = filter(x.entries, (e) => e.name == "Beta")
