    keyed = List.keyBy(x.entries, (e) => e.name)
    write crm-[:companies]-> { name: "${count(kept)}|${total}|${count(grouped[FIRST(x.entries).name])}|${keyed[FIRST(x.entries).name].name}" }
  })
}

