  found-[e:entry]-> { write deduped-[:entries]-> { unique by (name), ?...e } }
  deduped-[x:entries]-> {
    if x.stage != null {
      write crm-[:companies]-> { name: x.name, stage: x.stage }
    } else {
      write crm-[:companies]-> { name: x.name, thesis: "no stage" }
    }
  }
}

