import { email, attio } from adapters
import { dealflow_inbox, acme_main } from credentials
import { vcUrlRetrieval as vc_url_retrieval } from plugins

inbox = connect email using dealflow_inbox
crm   = connect attio using acme_main

function carry(msg: <inbox-[:message]->>) {
  deal = extract from [msg.`text`] through [vc_url_retrieval] {
    name: "the company name"
  }

  co = write crm-[:companies]-> {
    unique by (`name`)
    name: deal.`name`
  }

  deal-[r:_resources WHERE r.type == "FILE"]-> {
    write crm-[:companies]-> {
      unique by (`name`)
      name: r.`url`
      deck: r.`file`
    }
  }
}

