crm   = connect attio using acme_main
node Co: "each company named" {
  name: <text> "its name"
  stage: <text> "its stage"
}
type Tier = <"gold" | "silver">

function trail(n: <number>): <text> {
  if (n <= 0) {
    return "end"
  }
  rest = trail(n - 1)
  return Text.concat("${n}", ",", rest)
}
function m(msg: <inbox-[:message]->>) {
  x = trail(3)
  write crm-[:notes]-> { body: x }
}

