import { email, attio } from adapters
import { dealflow_inbox, acme_main } from credentials
inbox = connect email using dealflow_inbox
crm   = connect attio using acme_main
node Company {
  name: <text>
  stage: <text>
  node founder {
    first: <text>
  }
}
function m(msg: <inbox-[:message]->>) {
  held = node { cos: lazy crm-[c:companies]->, names: lazy crm-[c:companies]-> node { label: c.`name` } }
  held-[c:cos]-> {
    write crm-[:notes]-> { body: c.`name` }
  }
  held-[n:names]-> {
    write crm-[:notes]-> { body: n.`label` }
  }
  cos = lazy crm-[c:companies]->
  if (cos != null) {
    write crm-[:companies]-> { name: Text.join(cos.`name`, ", ") }
  }
}

