crm = connect attio using acme_main
function m(msg: <inbox-[:message]->>) {
  co = write crm-[:companies]-> { name: "Acme" }
  pe = write crm-[:people]-> { name: "Ada" }
  found = match (co-[:notes]->, pe-[:notes]->) { unique by (`body`), body: msg.`subject` }
  write crm-[:notes]-> { body: found == null ? "absent" : found.`body` }
}

