import { dealflow_inbox, acme_main } from credentials
inbox = connect email using dealflow_inbox
crm = connect attio using acme_main
function m(msg: <inbox-[:message]->>) {
  r = all(
    () => {
      a = write crm-[:companies]-> { name: "arm 0" }
      await sleep(1h)
      return a
    },
    () => 2
  )
  h = r[0]
  write crm-[:notes]-> { body: Text.concat(coalesce(r[0].name, "none"), "/", coalesce(h.name, "none"), "/", (r[0] == null ? "missing" : "held"), "/", r[1]) }
