import { email, attio } from adapters
import { inbox_cred, acme_main } from credentials
inbox = connect email using inbox_cred
function m(msg: <inbox-[:message]->>) {
  crm = connect attio using acme_main
  rehearsed = connect attio using acme_main { dryRun: true }
  h0 = write crm-[:companies]-> { unique by (FUZZY `name`), name: "Acme Incorporated", domain : "new.example" }
  h0-[w1:@old WHERE w1.`domain` == "new.example"]-> {
    write crm-[:notes]-> { title: coalesce(w1.`name`, "none") }
  }
  m2 = match crm-[:companies]-> { unique by (`name`), name: "Acme Incorporated" }
  write crm-[:notes]-> { title: m2 == null ? "absent" : COALESCE(m2.`domain`, "none") }
  if (m2 != null) {
    x3 = write m2 { domain: "old.example" }
    write crm-[:notes]-> { title: coalesce(m2.`domain`, "none") }
    write crm-[:notes]-> { title: FIRST(x3-[:@old]->) == x3 ? "self" : "other" }
  }
}

