inbox = connect email using inbox_cred
function m(msg: <inbox-[:message]->>) {
  crm = connect attio using acme_main
  rehearsed = connect attio using acme_main { dryRun: true }
  h0 = write crm-[:companies]-> { unique by (FUZZY `name`), name: "Acme Incorporated", domain : "second.example" }
  if true {
    write crm-[:notes]-> { title: FIRST(h0-[:@old]->) == h0 ? "self" : "other" }
  }
  h1 = write crm-[:companies]-> { name: "Acme Incorporated", domain : "second.example" }
  h2 = write rehearsed-[:companies]-> { name: "Beta Ltd", domain ?: "new.example" }
  map(["Beta Ltd", "Beta Ltd"], (n) => {
    o3 = write rehearsed-[:companies]-> { unique by (`name`), name: n, domain : "third.example" }
    o3-[w4:@old]-> {
      write crm-[:notes]-> { title: coalesce(w4.`domain`, "none") }
    }
  })
  h5 = write rehearsed-[:companies]-> { unique by (`name`), name: "Newco", domain ?: "second.example" }
}

