inbox = connect email using inbox_cred
function m(msg: <inbox-[:message]->>) {
  crm = connect attio using acme_main
  rehearsed = connect attio using acme_main { dryRun: true }
  h0 = write crm-[:companies]-> { unique by (FUZZY `name`), name: "Newco", domain : "third.example" }
  map(["Acme Incorporated", "Acme Incorporated"], (n) => {
    o1 = write rehearsed-[:companies]-> { unique by (`name`), name: n, domain : "new.example" }
    write crm-[:notes]-> { title: EXISTS(o1-[:@old]->) ? "matched" : "created" }
  })
  h2 = write rehearsed-[:companies]-> { unique by (`name`), name: "Newco", domain : "new.example" }
  write crm-[:notes]-> { title: coalesce(first(h0-[:@old]->).`domain`, "none") }
  write crm-[:notes]-> { title: EXISTS(h2-[:@old]->) ? "matched" : "created" }
  map(["Newco", "Acme Incorporated"], (n) => {
    o3 = write crm-[:companies]-> { unique by (`name`), name: n, domain : "new.example" }
    write crm-[:notes]-> { title: FIRST(o3-[:@old]->) == o3 ? "self" : "other" }
  })
}

