inbox = connect email using inbox_cred
function m(msg: <inbox-[:message]->>) {
  crm = connect attio using acme_main
  rehearsed = connect attio using acme_main { dryRun: true }
  h0 = write crm-[:companies]-> { unique by (`name`), name: "Beta Ltd", domain : "old.example" }
  h1 = write crm-[:companies]-> { unique by (`name`), name: "Beta Ltd", domain : "third.example" }
  await sleep(1h)
  map(["Acme Incorporated", "Newco"], (n) => {
    o2 = write rehearsed-[:companies]-> { unique by (`name`), name: n, domain : "old.example" }
    write crm-[:notes]-> { title: exists(o2-[w3:@old WHERE w3.`name` == o2.`name`]->) ? "kept" : "not" }
  })
  write crm-[:notes]-> { title: exists(h1-[:@old]->) ? "matched" : "created" }
  h4 = write crm-[:companies]-> { name: "Beta Ltd", domain : "new.example" }
}

