function m(msg: <inbox-[:message]->>) {
  crm = connect attio using acme_main
  rehearsed = connect attio using acme_main { dryRun: true }
  h0 = write crm-[:companies]-> { unique by (`name`), name: "Newco", domain ?: "third.example" }
  write crm-[:notes]-> { title: "${count(h0-[:@old]->)}" }
  h1 = write crm-[:companies]-> { unique by (`name`), name: "Newco", domain : "old.example" }
  h2 = write crm-[:companies]-> { unique by (`name`), name: "Newco", domain : "old.example" }
  m3 = match crm-[:companies]-> { unique by (`name`), name: "Newco" }
  write crm-[:notes]-> { title: m3 == null ? "absent" : COALESCE(m3.`domain`, "none") }
  if (m3 != null) {
    x4 = write m3 { domain: "new.example" }
    write crm-[:notes]-> { title: coalesce(m3.`domain`, "none") }
    x4-[w5:@old WHERE w5.`domain` == "old.example"]-> {
      write crm-[:notes]-> { title: coalesce(w5.`name`, "none") }
    }
  }
  h6 = write crm-[:companies]-> { unique by (`name`), name: "Acme Incorporated", domain : "second.example" }
  x7 = write h6 { domain : "old.example" }
  write crm-[:notes]-> { title: x7 == h6 ? "same" : "distinct" }
}

