inbox = connect email using inbox_cred
function m(msg: <inbox-[:message]->>) {
  crm = connect attio using acme_main
  rehearsed = connect attio using acme_main { dryRun: true }
  h0 = write rehearsed-[:companies]-> { unique by (`name`), name: "Beta Ltd", domain : "old.example" }
  write crm-[:notes]-> { title: "${count(h0-[:@old]->)}" }
  map(["Newco", "Acme Incorporated"], (n) => {
    o1 = write crm-[:companies]-> { unique by (`name`), name: n, domain : "third.example" }
    write crm-[:notes]-> { title: FIRST(o1-[:@old]->) == o1 ? "self" : "other" }
  })
  m2 = match crm-[:companies]-> { unique by (`name`), name: "Newco" }
  write crm-[:notes]-> { title: m2 == null ? "absent" : COALESCE(m2.`domain`, "none") }
  if (m2 != null) {
    write crm-[:notes]-> { title: coalesce(m2.`name`, "none") }
  }
}

