inbox = email(credentials: inbox_cred)
movement m(msg: <inbox-[:message]->>) {
  crm = attio(credentials: acme_main)
  rehearsed = attio(credentials: acme_main, dry_run: true)
  h0 = write crm-[:companies]-> { unique by (FUZZY `name`), name: "Newco", domain : "third.example" }
  m1 = match crm-[:companies]-> { unique by (`name`), name: "Beta Ltd" }
  write crm-[:notes]-> { title: IF m1 == null THEN "absent" ELSE COALESCE(m1.`domain`, "none") END }
  if m1 != null {
    write crm-[:notes]-> { title: COALESCE(m1.`name`, "none") }
  }
  crm-[c2:companies]-> {
    x3 = write c2 { domain: "second.example" }
    write crm-[:notes]-> { title: COALESCE(x3.`domain`, "none") }
  }
  write h0 { domain: "old.example" }
  await sleep(1h)
  write h0 { domain: "third.example" }
}

