movement m(msg: <inbox-[:message]->>) {
  crm = attio(credentials: acme_main)
  rehearsed = attio(credentials: acme_main, dry_run: true)
  h0 = write crm-[:companies]-> { unique by (`name`), name: "Acme Incorporated", domain : "old.example" }
  h1 = write crm-[:companies]-> { unique by (`name`), name: "Acme Incorporated", domain : "old.example" }
  MAP(["Beta Ltd", "Newco"], (n) => {
    o2 = write rehearsed-[:companies]-> { unique by (`name`), name: n, domain ?: "new.example" }
    write crm-[:notes]-> { title: COALESCE(FIRST(o2-[:@old]->).`domain`, "none") }
  })
  MAP(["Acme Incorporated", "Beta Ltd"], (n) => {
    o3 = write crm-[:companies]-> { unique by (`name`), name: n, domain : "third.example" }
    write crm-[:notes]-> { title: IF FIRST(o3-[:@old]->) == o3 THEN "self" ELSE "other" END }
  })
  h4 = write crm-[:companies]-> { unique by (FUZZY `name`), name: "Acme Incorporated", domain : "third.example" }
  crm-[c5:companies]-> {
    x6 = write c5 { domain: "old.example" }
    write crm-[:notes]-> { title: COALESCE(x6.`name`, "none") }
  }
}

