import { fetchUrl as fetch_url, summarise, relay } from plugins

inbox = connect email using inbox_cred
src = connect attio using crm_cred
sink = connect sheets using sheet_cred
node Entry: "each company named in this message" {
  name: <text> "the company's name"
  tag: <text> "its tag"
  node child: "each founder" {
    first: <text> "first name"
  }
}
node Holder {
  name: <text>
  node entries {
    name: <text>
    tag: <text>
    node child {
      first: <text>
    }
  }
}
function use_entry(e: <Entry>) {
  write sink-[:rows]-> { v: e.name }
}
function pairs_entry(e: <Entry>) {
  write sink-[:rows]-> { v: Text.pairs(e) }
}
function serialise_entry(e: <Entry>) {
  write sink-[:rows]-> { v: Json.stringify(e) }
}
function child_entry(e: <Entry>) {
  e-[k:child]-> {
    write sink-[:rows]-> { v: k.first }
  }
}
function serialise_child(e: <Entry>) {
  e-[k:child]-> {
    write sink-[:rows]-> { v: Json.stringify(k) }
  }
}
function summarise_entry(e: <Entry>) {
  s = summarise(e)
  write sink-[:rows]-> { v: s }
}
function run_cell(msg: <inbox-[:message]->>) {
  deduped = node { entries: <Entry> order by arrival }
  copies = node { entries: <Entry> order by arrival }
  a = write deduped-[:entries]-> { name: "Acme", tag: "a" }
  write a-[:child]-> { first: "Ann" }
  b = write deduped-[:entries]-> { name: "Beta", tag: "b" }
  write b-[:child]-> { first: "Bob" }
  deduped-[e:entries]-> {
    m = { k: e }
    write sink-[:rows]-> { v: "s", ?...m.k }
  }
}

