import { email, attio, slack } from adapters
import { acme_main, acme_workspace } from credentials

inbox = connect email
crm   = connect attio using acme_main
team  = connect slack using acme_workspace

function race_sync(msg: <inbox-[:message]->>) {
  r = await race([
    () => {
      made = write crm-[:companies]-> {
        unique by (`domains`)
        name:    msg.`subject`
        domains: [msg.`text`]
      }
      return made.externalId
    },
    () => { return true },
  ])
  write team-[:messages]-> {
    channel: "#c"
    text:    "id=${r[0]}"
  }
  write team-[:messages]-> {
    channel: "#c2"
    text:    "flag=${r[1]}"
  }
}

