import { email, attio, slack, affinity } from adapters
import { acme_main, acme_workspace, acme_affinity } from credentials

inbox = connect email
crm   = connect attio using acme_main
team  = connect slack using acme_workspace
aff   = connect affinity using acme_affinity

function dealflow_intake(msg: <inbox-[:message]->>) {

  company = write crm-[:companies]-> {
    unique by (`domains`)
    name:    msg.`subject`
    domains: [msg.`text`]
  }

  write team-[:messages]-> {
    channel: "#dealflow"
    text:    "New deal from ${msg.`subject`}: ${company.externalId}"
  }

  write aff-[:organization]-> {
    unique by (`name`)
    name:      company.`name`
    attio_url: company.externalId
  }
}

