import { team_drive, acme_main } from credentials

inbox = connect email
function intake(msg: <inbox-[:message]->>) {
  g = graph { files: msg-[:files]-> }
  done = map(["a", "b", "c", "d"], (i) => {
    if (i == "a" || i == "c") {
      write g-[:files]-> { unique by (filename), filename: "x.pdf", contentType ?: i }
    }
    if (i == "b" || i == "d") {
      msg-[f:files]-> {
        write f { contentType ?: i }
      }
    }
    return i
  }, { concurrency: 4 })
}

