inbox = connect email using dealflow_inbox
kg    = connect graph using graph_main
function m(msg: <inbox-[:message]->>) {
  n = count(kg-[c:company WHERE c.`stage` == "Seed" ORDER BY c.`revenue` DESC LIMIT 2]->)
  top = first(kg-[c:company WHERE c.`stage` == "Seed" ORDER BY c.`revenue` DESC LIMIT 2]->)
  names = Text.join(kg-[c:company WHERE c.`stage` == "Seed" ORDER BY c.`revenue` DESC LIMIT 2]->.`name`, ", ")
  write kg-[:note]-> { text: "${n} ${top.`name`} ${names}" }
}

import { email, graph } from adapters
