import { email, graph } from adapters
import { dealflow_inbox, graph_main } from credentials
inbox = connect email using dealflow_inbox
kg    = connect graph using graph_main
function m(msg: <inbox-[:message]->>) {
  xs = [3, null, "4", 1]
  rows = [{ n: "b", s: 2 }, { n: "a", s: 9 }, { n: "c" }]
  write kg-[:note]-> { text: "${count(xs)} ${List.sum(xs)} ${List.avg(xs)} ${List.min([2, 0, 5])} ${List.max(xs)} ${first(xs)} ${List.last(xs)} ${Text.join(xs, "/")} ${count(List.from(7))}" }
  write kg-[:note]-> { text: Text.join(sort(["b", "a", "c"], { order: "desc" }), "") }
  write kg-[:note]-> { text: Text.join(sort([2, 10, 1]), "") }
  ranked = sort(rows, (r) => r.s, { order: "desc" })
  r0 = ranked[0]
  r1 = ranked[1]
  r2 = ranked[2]
  pair = [null, 5]
  write kg-[:note]-> { text: "${r0.n}${r1.n}${r2.n} ${only(pair)}" }
}

