    company: msg.`subject`
  }
  inv = write graph-[:investor]-> {
    unique by (`name`)
    name: msg.`text`
  }
  write (fr-[:participants]->, fr-[:related]->) {
    unique by (fr && inv)
    name: msg.`text`
  }
}

