import { slack } from adapters
chat = connect slack
type Thesis = <"Consumer" | "Infra">
node Company: "each company named" {
  name: <text> "its name"
  employees: <number> "its headcount"
}
function double(n: <number>) {
  return n * 2
}
function label(t: <text>) {
  return Text.upper(t)
}
function ask_model(t: <text>) {
  return ai("Summarise: ${t}")
}
function waits(n: <number>) {
  await sleep(1h)
  return n
}

function scan(c: <chat-[:channel]->>) {
  ask = (t: <text>) => ai("Summarise: ${t}")
  x = 1
}
listen to chat fire scan

