import { slack, affinity } from adapters
import { dev_slack, acme_drive } from credentials

inbox = connect slack using dev_slack
drive = connect affinity using acme_drive

function weekly_report(msg: <inbox-[:message]->>) {
  items = msg-[f:files]-> {
    return "- ${f.`name`}"
  }
  digest = "Files from ${msg.`user`}: ${Text.join(items, ", ")}"
  write drive-[:report]-> {
    slug:   Text.slug(msg.`user`)
    amount: Currency.numberFromFigure(msg.`text`)
    code:   Currency.codeFromFigure(msg.`text`)
    due:    Date.addDays("2026-03-12", 7)
    report: File.from(digest, "pdf")
  }
}

